<h1>Relatórios de vendas</h1><div class="cards"><div class="metric"><span>Vendas de hoje</span><strong><?= (int)$resumo['quantidade'] ?></strong></div><div class="metric"><span>Faturamento de hoje</span><strong><?= money($resumo['faturamento']) ?></strong></div></div><section class="panel"><h2>Histórico de vendas</h2><div class="table-wrap"><table><tr><th>Nº</th><th>Data</th><th>Cliente</th><th>Pagamento</th><th>Total</th></tr><?php foreach($vendas as $v): ?><tr><td>#<?= (int)$v['id'] ?></td><td><?= date('d/m/Y H:i',strtotime($v['data_venda'])) ?></td><td><?= e($v['cliente_nome'] ?? 'Não identificado') ?></td><td><?= e($v['forma_pagamento']) ?></td><td><?= money($v['total']) ?></td></tr><?php endforeach; ?></table></div><?php if(!$vendas): ?><p>Nenhuma venda registrada ainda.</p><?php endif; ?></section><?php require __DIR__.'/../layouts/footer.php'; ?>
